CREATE TABLE delivery_cursors(owner TEXT PRIMARY KEY REFERENCES owners(owner),start_after INTEGER NOT NULL CHECK(start_after>=0),through INTEGER NOT NULL CHECK(through>=start_after));
CREATE TABLE delivery_messages(owner TEXT NOT NULL REFERENCES owners(owner),identity TEXT NOT NULL,source_seq INTEGER NOT NULL,document_json TEXT NOT NULL,relays_json TEXT NOT NULL,created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(owner,identity),UNIQUE(owner,source_seq));
CREATE TABLE delivery_branches(owner TEXT NOT NULL,branch TEXT NOT NULL,cycle INTEGER NOT NULL,member TEXT NOT NULL,generation TEXT NOT NULL,target_json TEXT NOT NULL,starter TEXT NOT NULL,PRIMARY KEY(owner,branch),FOREIGN KEY(owner,starter) REFERENCES delivery_messages(owner,identity));
CREATE TABLE delivery_destinations(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,branch TEXT,target_json TEXT NOT NULL,PRIMARY KEY(owner,identity,destination),FOREIGN KEY(owner,identity) REFERENCES delivery_messages(owner,identity));
CREATE TABLE delivery_unsigned(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,document_json TEXT NOT NULL,PRIMARY KEY(owner,identity,destination),FOREIGN KEY(owner,identity,destination) REFERENCES delivery_destinations(owner,identity,destination));
CREATE TABLE delivery_signed(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,event_id TEXT NOT NULL UNIQUE,event_json TEXT NOT NULL,PRIMARY KEY(owner,identity,destination),FOREIGN KEY(owner,identity,destination) REFERENCES delivery_unsigned(owner,identity,destination));
CREATE TABLE delivery_receipts(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,relay TEXT NOT NULL,acknowledged_at INTEGER NOT NULL CHECK(acknowledged_at>=0),PRIMARY KEY(owner,identity,destination,relay),FOREIGN KEY(owner,identity,destination) REFERENCES delivery_signed(owner,identity,destination));
CREATE TABLE delivery_work(owner TEXT NOT NULL,identity TEXT NOT NULL,destination TEXT NOT NULL,lease_id TEXT,lease_until INTEGER NOT NULL DEFAULT 0,attempted_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,identity,destination),FOREIGN KEY(owner,identity,destination) REFERENCES delivery_destinations(owner,identity,destination));
CREATE TABLE delivery_overlay(owner TEXT NOT NULL,identity TEXT NOT NULL,event_seq INTEGER,attempted_at INTEGER NOT NULL DEFAULT 0 CHECK(attempted_at>=0),PRIMARY KEY(owner,identity),FOREIGN KEY(owner,identity) REFERENCES delivery_messages(owner,identity));
CREATE TABLE delivery_expansions(owner TEXT NOT NULL,identity TEXT NOT NULL,conversation_json TEXT NOT NULL,PRIMARY KEY(owner,identity),FOREIGN KEY(owner,identity) REFERENCES delivery_messages(owner,identity));
CREATE TRIGGER immutable_delivery_cursor BEFORE UPDATE ON delivery_cursors WHEN NEW.owner IS NOT OLD.owner OR NEW.start_after IS NOT OLD.start_after OR NEW.through<OLD.through BEGIN SELECT RAISE(ABORT,'delivery cursor cannot rewind'); END;
CREATE TRIGGER retained_delivery_cursor BEFORE DELETE ON delivery_cursors BEGIN SELECT RAISE(ABORT,'delivery cursor is retained'); END;
CREATE TRIGGER immutable_delivery_message BEFORE UPDATE ON delivery_messages BEGIN SELECT RAISE(ABORT,'member message is frozen'); END;
CREATE TRIGGER retained_delivery_message BEFORE DELETE ON delivery_messages BEGIN SELECT RAISE(ABORT,'member message is retained'); END;
CREATE TRIGGER immutable_delivery_branch BEFORE UPDATE ON delivery_branches BEGIN SELECT RAISE(ABORT,'member branch is frozen'); END;
CREATE TRIGGER retained_delivery_branch BEFORE DELETE ON delivery_branches BEGIN SELECT RAISE(ABORT,'member branch is retained'); END;
CREATE TRIGGER immutable_delivery_destination BEFORE UPDATE ON delivery_destinations BEGIN SELECT RAISE(ABORT,'member destination is frozen'); END;
CREATE TRIGGER retained_delivery_destination BEFORE DELETE ON delivery_destinations BEGIN SELECT RAISE(ABORT,'member destination is retained'); END;
CREATE TRIGGER immutable_delivery_unsigned BEFORE UPDATE ON delivery_unsigned BEGIN SELECT RAISE(ABORT,'member unsigned fields are frozen'); END;
CREATE TRIGGER retained_delivery_unsigned BEFORE DELETE ON delivery_unsigned BEGIN SELECT RAISE(ABORT,'member unsigned fields are retained'); END;
CREATE TRIGGER immutable_delivery_signed BEFORE UPDATE ON delivery_signed BEGIN SELECT RAISE(ABORT,'member signed bytes are frozen'); END;
CREATE TRIGGER retained_delivery_signed BEFORE DELETE ON delivery_signed BEGIN SELECT RAISE(ABORT,'member signed bytes are retained'); END;
CREATE TRIGGER immutable_delivery_receipt BEFORE UPDATE ON delivery_receipts BEGIN SELECT RAISE(ABORT,'member publication receipt is immutable'); END;
CREATE TRIGGER retained_delivery_receipt BEFORE DELETE ON delivery_receipts BEGIN SELECT RAISE(ABORT,'member publication receipt is retained'); END;
CREATE TRIGGER immutable_delivery_expansion BEFORE UPDATE ON delivery_expansions BEGIN SELECT RAISE(ABORT,'legacy conversation resolution is frozen'); END;
CREATE TRIGGER retained_delivery_expansion BEFORE DELETE ON delivery_expansions BEGIN SELECT RAISE(ABORT,'legacy conversation resolution is retained'); END;
CREATE TRIGGER monotone_delivery_overlay BEFORE UPDATE ON delivery_overlay WHEN NEW.owner IS NOT OLD.owner OR NEW.identity IS NOT OLD.identity OR (OLD.event_seq IS NOT NULL AND NEW.event_seq IS NOT OLD.event_seq) BEGIN SELECT RAISE(ABORT,'overlay receipt cannot change'); END;
CREATE TRIGGER retained_delivery_overlay BEFORE DELETE ON delivery_overlay BEGIN SELECT RAISE(ABORT,'overlay receipt is retained'); END;
